import os, re, json

pdf_names = [
    \"NVIDIA-Nemotron-3-Super-Technical-Report.pdf\",
    \"NVIDIA-Nemotron-Nano-V2-VL-report.pdf\",
    \"Nemotron3_Efficient_And_Open_Intelligence.pdf\"
]
base = \"data/documents\"
points = []
for name in pdf_names:
    path = os.path.join(base, name)
    try:
        with open(path, \"rb\") as f:
            data = f.read()
        try:
            text = data.decode(\"utf-8\", errors=\"ignore\")
        except Exception:
            text = data.decode(\"latin-1\", errors=\"ignore\")
        sentences = re.split(r'(?<=[.!?])\s+', text)
        point = None
        for s in sentences:
            if \"Nemotron\" in s:
                point = s.strip()
                break
        if not point:
            point = text[:100].strip()
        points.append({
            \"point\": point,
            \"source_path\": os.path.relpath(path, start=\".\")
        })
    except Exception as e:
        points.append({
            \"point\": f\"Error reading {name}: {e}\",
            \"source_path\": os.path.relpath(path, start=\".\")
        })
print(json.dumps(points, ensure_ascii=False, indent=2))

